n31233.content:
\begin{lemma}[boundary exception]
\label{boundary-exception}
\leanok
\lean{boundary_exception}

Let $\mathcal{L}({\mathfrak u})$ be as defined in \eqref{eq-L-def}. We have for each ${\mathfrak u}\in {\mathfrak U}_1(k,n,l)$,
\begin{equation}
\mu(\bigcup_{I\in \mathcal{L}({\mathfrak u})} I)
\le D^{1-\kappa Z(n+1)}
        \mu({\mathcal{I}}(\mathfrak{u})).
\end{equation}
\end{lemma}

n31236.content:
\begin{proof}
\leanok
As each ${\mathfrak p}\in {\mathfrak L}_4(k,n,j)$
is contained in $\cup\mathcal{L}({\mathfrak u})$ for some
${\mathfrak u}\in {\mathfrak U}_1(k,n,l)$, we have
\begin{equation}
\mu(\bigcup_{{\mathfrak p}\in {\mathfrak L}_4 (k,n,j)}{\mathcal{I}}({\mathfrak p}))
\le \sum_{{\mathfrak u}\in {\mathfrak U}_1(k,n,j)}
\mu(\bigcup_{I \in \mathcal{L} ({\mathfrak u})}I).
\end{equation}
Using \Cref{boundary-exception} and then \Cref{tree-count}, we estimate this further
 by
\begin{equation}
    \le \sum_{{\mathfrak u}\in {\mathfrak U}_1(k,n,j)}
    D^{1-\kappa Z(n+1)}
        \mu({\mathcal{I}}(\mathfrak{u}))
\end{equation}
\begin{equation}
    \le 2^{100a^2+9a+1-j} \sum_{\mathfrak{m}\in \mathfrak{M}(k,n)}
     D^{-\kappa Z(n+1)}
    \mu({\mathcal{I}}(\mathfrak{m}))\,.
\end{equation}
Using \Cref{top-tiles}, we estimate this by
  \begin{equation}
     \le
2^{100a^2 + 9a + 1-j} D^{-\kappa Z(n+1)}
     2^{n+k+3}\mu(G)\, .
\end{equation}
Now we estimate $G_3$ defined in \eqref{defineg3} by
\begin{equation}
    \mu(G_3)\le \sum_{k\ge 0}\, \sum_{n \geq k}\,
    \sum_{0\le j\le 2n+3}
    \mu(\bigcup_{{\mathfrak p}\in {\mathfrak L}_4 (k,n,j)}
    {\mathcal{I}}({\mathfrak p}))
\end{equation}
\begin{equation}
    \le \sum_{k\ge 0}\, \sum_{n \geq k}\,
    \sum_{0\le j\le 2n+3}
    2^{100a^2 + 9a + 3 + n + k -j} D^{-\kappa Z(n+1)}\mu(G)
\end{equation}
Summing geometric series, using that $D^{\kappa Z}\ge 8$ by \eqref{defineD}, \eqref{definekappa} and \eqref{defineZ}, we estimate this by
\begin{equation}
    \le \sum_{k\ge 0}\, \sum_{n \geq k}\,
    2^{100a^2 + 9a + 4 + n + k} D^{-\kappa Z(n+1)}\mu(G)
\end{equation}
\begin{equation}
    = \sum_{k\ge 0} 2^{100a^2 + 9a + 4 + 2k} D^{-\kappa Z(k+1)} \sum_{n \geq k}\,
    2^{n - k} D^{-\kappa Z(n-k)}\mu(G)
\end{equation}
\begin{equation}
    \le \sum_{k\ge 0} 2^{100a^2 + 9a + 5 + 2k} D^{-\kappa Z(k+1)}\mu(G)
\end{equation}
\begin{equation}
   \le 2^{100a^2 + 9a + 6} D^{-\kappa Z}\mu(G)
\end{equation}
Using $D = 2^{100a^2}$ and $a \ge 4$ and $\kappa Z \ge 2$ by \eqref{defineD} and \eqref{definekappa} proves the lemma.
\end{proof}

