n31242.content:
\begin{lemma}[wiggle order 3]
\label{wiggle-order-3}
\leanok
\lean{wiggle_order_11_10, wiggle_order_100, wiggle_order_500}
\uses{wiggle-order-1, wiggle-order-2}
    The following implications hold for all ${\mathfrak q}, {\mathfrak q}' \in {\mathfrak P}$:
    % Note: some fixes were suggested by Georges Gonthier
    % Note: we basically use {eq-sc1} in chapter 6. Mention this.
    \begin{equation}
        \label{eq-sc1}
        {\mathfrak q}\le {\mathfrak q}' \ \text{and} \ \lambda \ge 1.1 \implies \lambda {\mathfrak q}\lesssim \lambda {\mathfrak q}'\,,
    \end{equation}
    \begin{equation}
        \label{eq-sc2}
        10{\mathfrak q}\lesssim {\mathfrak q}' \ \text{and} \ {\mathcal{I}}({\mathfrak q}) \ne {\mathcal{I}}({\mathfrak q}') \implies 100 {\mathfrak q}\lesssim 100 {\mathfrak q}'\,,
    \end{equation}
    \begin{equation}
        \label{eq-sc3}
        2{\mathfrak q}\lesssim {\mathfrak q}' \ \text{and} \ {\mathcal{I}}({\mathfrak q}) \ne {\mathcal{I}}({\mathfrak q}') \implies 4 {\mathfrak q}\lesssim 500 {\mathfrak q}'\,.
    \end{equation}
\end{lemma}

