n31248.content:
\begin{lemma}[C1 convex]
    \label{C1-convex}
    \leanok
    \lean{ordConnected_C1}
    \uses{C-convex}
    For each $k,n,j$, the collection ${\mathfrak C}_1(k,n,j)$ is convex.
\end{lemma}

n31249.content:
\begin{proof}
    \leanok
    Let ${\mathfrak p}\le{\mathfrak p}'\le{\mathfrak p}''$ with ${\mathfrak p}, {\mathfrak p}'' \in {\mathfrak C}_1(k,n,j)$. By \Cref{C-convex} and the inclusion ${\mathfrak C}_1(k,n,j) \subset {\mathfrak C}(k,n)$, which holds by definition \eqref{defcnkj}, we have ${\mathfrak p}' \in {\mathfrak C}(k,n)$. By \eqref{eq-sc1} and transitivity of $\lesssim$ we have that ${\mathfrak q}\le {\mathfrak q}'$ and $100 {\mathfrak q}' \lesssim \mathfrak{m}$ imply $100 {\mathfrak q}\lesssim \mathfrak{m}$. So, by \eqref{defbfp}, $\mathfrak{B}({\mathfrak p}'') \subset \mathfrak{B}({\mathfrak p}') \subset \mathfrak{B}({\mathfrak p})$. Consequently, by \eqref{defcnkj}
    $$
        2^j \le |\mathfrak{B}({\mathfrak p}'')|\le |\mathfrak{B}({\mathfrak p}')| \le |\mathfrak{B}({\mathfrak p})| < 2^{j+1}\,,
    $$
    thus ${\mathfrak p}' \in {\mathfrak C}_1(k,n,j)$.
\end{proof}

