n31258.content:
\begin{lemma}[dens compare]
    \label{dens-compare}
    \leanok
    \lean{dens1_le_dens'}
    We have for every $k\ge 0$ and ${\mathfrak P}'\subset {\mathfrak P}(k)$
\begin{equation}
    \dens_1({\mathfrak P}')\le \dens_k'({\mathfrak P}')\, .
\end{equation}
\end{lemma}

n31259.content:
\begin{proof}
\leanok
It suffices to show that for all ${\mathfrak p}'\in {\mathfrak P}'$
and $\lambda\ge 2$ and ${\mathfrak p}\in {\mathfrak P}({\mathfrak P}')$ with $\lambda {\mathfrak p}' \lesssim \lambda {\mathfrak p}$ we have
\begin{equation}
    \frac{\mu({E}_2(\lambda, {\mathfrak p}))}{\mu({\mathcal{I}}({\mathfrak p}))}
    \le \sup_{{\mathfrak p}'' \in {\mathfrak P}(k): \lambda {\mathfrak p}' \lesssim \lambda {\mathfrak p}''}
    \frac{\mu({E}_2(\lambda, {\mathfrak p}''))}{\mu({\mathcal{I}}({\mathfrak p}''))}.
\end{equation}
    Let such ${\mathfrak p}'$, $\lambda$, ${\mathfrak p}$ be given.
    It suffices to show that ${\mathfrak p}\in {\mathfrak P}(k)$,
    that is, it satisfies \eqref{muhj1}
    and \eqref{muhj2}.

We show \eqref{muhj1}.
 As ${\mathfrak p}\in {\mathfrak P}({\mathfrak P}')$, there exists
${\mathfrak p}''\in {\mathfrak P}'$ with ${\mathcal{I}}({\mathfrak p}')\subset {\mathcal{I}}({\mathfrak p}'')$. By assumption on ${\mathfrak P}'$, we have ${\mathfrak p}''\in {\mathfrak P}(k)$ and there exists
$J\in \mathcal{D}$ with
   ${\mathcal{I}}({\mathfrak p}'')\subset J$ and
   \begin{equation}
       \mu(G\cap J)>2^{-k-1} \mu(J).
   \end{equation}
Then also ${\mathcal{I}}({\mathfrak p}')\subset J$, which proves
\eqref{muhj1} for ${\mathfrak p}$.

We show \eqref{muhj2}. Assume to get a contradiction that
there exists $J\in \mathcal{D}$ with
   ${\mathcal{I}}({\mathfrak p})\subset J$ and
   \begin{equation}\label{mugj}
       \mu(G\cap J)>2^{-k} \mu(J).
   \end{equation}
   As $\lambda{\mathfrak p}'\lesssim \lambda{\mathfrak p}$, we have ${\mathcal{I}}({\mathfrak p}')\subset {\mathcal{I}}({\mathfrak p})$, and therefore
    ${\mathcal{I}}({\mathfrak p}')\subset J$. This contradicts
   ${\mathfrak p}'\in {\mathfrak P}'\subset {\mathfrak P}(k)$. This proves
\eqref{muhj2} for ${\mathfrak p}$.
\end{proof}

