n31262.content:
\begin{lemma}[relation geometry]
    \label{relation-geometry}
    \leanok
    \lean{URel.eq, URel.not_disjoint}
    \uses{wiggle-order-3}
    If ${\mathfrak u}\sim {\mathfrak u}'$, then ${\mathcal{I}}(u) = {\mathcal{I}}(u')$ and
    \begin{equation*}
        B_{{\mathfrak u}}({\mathcal{Q}}({\mathfrak u}), 100) \cap B_{{\mathfrak u}'}({\mathcal{Q}}({\mathfrak u}'), 100) \neq \emptyset\ .
    \end{equation*}
\end{lemma}

n31263.content:
\begin{proof}
    \leanok
    Let ${\mathfrak u}, {\mathfrak u}' \in {\mathfrak U}_2(k,n,j)$ with ${\mathfrak u}\sim {\mathfrak u}'$. If ${\mathfrak u}= {\mathfrak u}'$ then the conclusion of the Lemma clearly holds. Else, there exists ${\mathfrak p}\in {\mathfrak C}_1(k,n,j)$ such that ${\mathcal{I}}({\mathfrak p}) \ne {\mathcal{I}}({\mathfrak u})$ and $2 {\mathfrak p}\lesssim {\mathfrak u}$ and $10 {\mathfrak p}\lesssim {\mathfrak u}'$.
    Using \Cref{wiggle-order-1} and \eqref{eq-sc2} of \Cref{wiggle-order-3}, we deduce that
    \begin{equation}
        \label{eq-Fefferman-trick0}
        100 {\mathfrak p}\lesssim 100 {\mathfrak u}\,, \qquad 100 {\mathfrak p}\lesssim 100{\mathfrak u}'\,.
    \end{equation}
    Now suppose that $B_{{\mathfrak u}}({\mathcal{Q}}({\mathfrak u}), 100) \cap B_{{\mathfrak u}'}({\mathcal{Q}}({\mathfrak u}'), 100) = \emptyset$. Then we have $\mathfrak{B}({\mathfrak u}) \cap \mathfrak{B}({\mathfrak u}') = \emptyset$, by the definition \eqref{defbfp} of $\mathfrak{B}$ and the definition \eqref{wiggleorder} of $\lesssim$, but also $\mathfrak{B}({\mathfrak u}) \subset \mathfrak{B}({\mathfrak p})$ and $\mathfrak{B}({\mathfrak u}') \subset \mathfrak{B}({\mathfrak p})$, by \eqref{defbfp}, \eqref{wiggleorder} and \eqref{eq-Fefferman-trick0}.
    Hence,
    $$
        |\mathfrak{B}({\mathfrak p})| \geq |\mathfrak{B}({\mathfrak u})| + |\mathfrak{B}({\mathfrak u}')| \geq 2^{j} + 2^j = 2^{j+1}\,,
    $$
    which contradicts ${\mathfrak p}\in {\mathfrak C}_1(k,n,j)$. Therefore we must have
    \begin{equation*}
        B_{{\mathfrak u}}({\mathcal{Q}}({\mathfrak u}), 100) \cap B_{{\mathfrak u}'}({\mathcal{Q}}({\mathfrak u}'), 100) \ne \emptyset\, .
    \end{equation*}

    It follows from $2{\mathfrak p}\lesssim {\mathfrak u}$ and $10{\mathfrak p}\lesssim {\mathfrak u}'$ that ${\mathcal{I}}({\mathfrak p}) \subset {\mathcal{I}}({\mathfrak u})$ and ${\mathcal{I}}({\mathfrak p}) \subset {\mathcal{I}}({\mathfrak u}')$. By \eqref{dyadicproperty}, it follows that ${\mathcal{I}}({\mathfrak u})$ and ${\mathcal{I}}({\mathfrak u}')$ are nested.
    Combining this with the conclusion of the last paragraph and definition \eqref{defunkj} of ${\mathfrak U}_1(k,n,j)$, we obtain that ${\mathcal{I}}({\mathfrak u}) = {\mathcal{I}}({\mathfrak u}')$.
\end{proof}

