\begin{lemma}[maximal bound antichain]
    \label{maximal-bound-antichain}
    \uses{tile-disjointness}
    \leanok
    \lean{maximal_bound_antichain}
    Let $x\in X$.
    Then
    \begin{equation}\label{hlmbound}
    | \sum_{{\mathfrak p}\in \mathfrak{A}}T_{{\mathfrak p}} f(x)|\le 2^{102 a^3} M_{\mathcal{B}} f (x) \, .
    \end{equation}
\end{lemma}

n31291.content:
\begin{proof}
\leanok
Fix $x\in X$. By \Cref{tile-disjointness}, there is at most one ${\mathfrak p}\in \mathfrak{A}$
such that
 $T_{{\mathfrak p}} f(x)$ is not zero.
 If there is no such ${\mathfrak p}$, the estimate \eqref{hlmbound} follows.

 Assume there is such a ${\mathfrak p}$.
 By definition of $T_{{\mathfrak p}}$ we have $x\in E({\mathfrak p})\subset {\mathcal{I}}({\mathfrak p})$ and by the squeezing property \eqref{eq-vol-sp-cube}
\begin{equation}\label{eqtttt0}
    \rho(x, {\mathrm{c}}({\mathfrak p}))\le 4D^{{\mathrm{s}}({\mathfrak p})}\, .
\end{equation}

Let $y\in X$ with $K_{{\mathrm{s}}({\mathfrak p})}(x,y)\neq 0$. By Definition \eqref{defks} of $K_{{\mathrm{s}}({\mathfrak p})}$
we have
\begin{equation}\label{supp-Ks1}
   \frac{1}{4} D^{{\mathrm{s}}({\mathfrak p})-1}
   \leq \rho(x,y) \leq \frac{1}{2} D^{{\mathrm{s}}({\mathfrak p})}\, .
\end{equation}
The triangle inequality with \eqref{eqtttt0} and \eqref{supp-Ks1} implies
\begin{equation}
    \rho({\mathrm{c}}({\mathfrak p}),y) < 8D^{{\mathrm{s}}({\mathfrak p})}\, .
\end{equation}
Using the kernel bound \eqref{eqkernel-size} and the lower bound in \eqref{supp-Ks}
we obtain
\begin{equation}
|K_{{\mathrm{s}}({\mathfrak p})}(x,y)|\le \frac{2^{a^3}}{\mu(B(x,\frac 14 D^{{{\mathrm{s}}({\mathfrak p})}-1}))}\, .
\end{equation}
Using $D=2^{100a^2}$
and the doubling property \eqref{doublingx} $5 +100a^2$ times estimates
the last display by
\begin{equation}
\le \frac{2^{5a+101a^3}}{\mu(B(x, 8D^{{\mathrm{s}}({\mathfrak p})}))}\,
\end{equation}
which, thanks to the closeness of the points $x$ and ${\mathrm{c}}({\mathfrak p})$ shown in \eqref{eqtttt0}, is in turn bounded by
\begin{equation}
\le \frac{2^{6a+101a^3}}{\mu(B({\mathrm{c}}({\mathfrak p}), 8D^{{\mathrm{s}}({\mathfrak p})}))}\, .
\end{equation}
 Using that {$|e({\vartheta})|$} is bounded by $1$
for every ${\vartheta}\in {\Theta}$, we estimate with the triangle inequality and the above information
 \begin{equation}
  | T_{{\mathfrak p}} f(x)|
    \le \frac{2^{6a+101 a^3}}{\mu(B({\mathrm{c}}({\mathfrak p}), 8D^{{\mathrm{s}}({\mathfrak p})}))} \int _{\mu(B({\mathrm{c}}({\mathfrak p}), 8D^{{\mathrm{s}}({\mathfrak p})}))} |f(y)|\, dy
  \end{equation}
This together with $a\ge 4$ proves the Lemma.
\end{proof}

