    \lean{dens1_antichain}
    \uses{Hardy-Littlewood, tile-correlation,antichain-tile-count}
Set $p:=4a^4$. We have
    \begin{equation}\label{eqttt3}
  \left|\int \overline{g(x)} \sum_{{\mathfrak p}\in \mathfrak{A}} T_{{\mathfrak p}} f(x)\, d\mu(x)\right|\le
