n31295.content:
\begin{proof}
\leanok
We write for the expression inside the absolute values on the left-hand side of \eqref{eqttt3}
\begin{equation}
  \sum_{{\mathfrak p}\in \mathfrak{A}}\iint \overline{g(x)} \mathbf{1}_{E({\mathfrak p})}(x)
  {K_{{\mathrm{s}}({\mathfrak p})}(x,y)}e({Q}(x)(y) -
   {Q}(x)(x))
   f(y)\, d\mu(y)\,d\mu(x)
\end{equation}
\begin{equation}
  =\int \sum_{{\mathfrak p}\in \mathfrak{A}} \overline{T_{{\mathfrak p}} ^*g(y)} f(y)\, d\mu(y)
\end{equation}
with the adjoint operator
\begin{equation}\label{eq-tstarwritten}
    T_{{\mathfrak p}}^*g(y)=\int_{E({\mathfrak p})} \overline{K_{{\mathrm{s}}({\mathfrak p})}(x,y)}e(-{Q}(x)(y)+
    {Q}(x)(x))g(x)\, d\mu(x)\, .
\end{equation}
We have by expanding the square
\begin{equation}
    \int \Big|\sum_{{\mathfrak p}\in \mathfrak{A}}T^*_{{\mathfrak p}}g(y)\Big|^2\, d\mu(y)=
    \int \left(\sum_{{\mathfrak p}\in \mathfrak{A}} T^*_{{\mathfrak p}}g(y)\right)
    \left(\sum_{{\mathfrak p}'\in \mathfrak{A}}\overline{T^*_{{\mathfrak p}'}g(y)}\right)\, d\mu(y)
\end{equation}
\begin{equation}\label{eqtts1}
    \le \sum_{{\mathfrak p}\in \mathfrak{A}} \sum_{{\mathfrak p}'\in \mathfrak{A}}
    \Big|\int T^*_{{\mathfrak p}}g(y)\overline{T^*_{{\mathfrak p}'}g(y)}\, d\mu(y)\Big|\,.
\end{equation}
We split the sum into the terms with ${\mathrm{s}}({\mathfrak p}')\le {\mathrm{s}}({\mathfrak p})$
and ${\mathrm{s}}({\mathfrak p})< {\mathrm{s}}({\mathfrak p}')$. Using the symmetry of each summand,
we may switch ${\mathfrak p}$ and ${\mathfrak p}'$ in the second sum. Using further positivity
of each summand to replace the condition ${\mathrm{s}}({\mathfrak p}')< {\mathrm{s}}({\mathfrak p})$
