\begin{lemma}[tile range support]\label{tile-range-support}
    \leanok
    \lean{Tile.range_support}
        For each ${\mathfrak p}\in {\mathfrak P}$, and each $y\in X$, we have that
    \begin{equation}\label{tstargnot0}
         T_{{\mathfrak p}}^* g(y)\neq 0
    \end{equation}
       implies
    \begin{equation}\label{ynotfar}
        y\in B({\mathrm{c}}({\mathfrak p}),5D^{{\mathrm{s}}({\mathfrak p})})\, .
    \end{equation}
    \end{lemma}

n31302.content:
\begin{proof}
    \leanok
    Fix ${\mathfrak p}$ and $y$ with \eqref{tstargnot0}.
    Then there exists $x\in E({\mathfrak p})$ with
    \begin{equation}
       \overline{K_{{\mathrm{s}}({\mathfrak p})}(x,y)}e(-{Q}(x)(y)
        +{Q}(x)(x))g(x) \neq 0\, .
    \end{equation}
    As $E({\mathfrak p})\subset {\mathcal{I}}({\mathfrak p})$ and by the squeezing property
    \eqref{eq-vol-sp-cube}, we have
    \begin{equation}
        \rho(x,{\mathrm{c}}({\mathfrak p})) < 4D^{{\mathrm{s}}({\mathfrak p})}\, .
    \end{equation}
    As $K_{{\mathrm{s}}({\mathfrak p})}(x,y)\neq 0$, we have by \eqref{supp-Ks}
    that
    \begin{equation}
    \rho(x,y)\le \frac 12 D^{{\mathrm{s}}({\mathfrak p})}\, .
    \end{equation}
    Now \eqref{ynotfar} follows by the triangle inequality.
\end{proof}

