\begin{lemma}\label{tile-uncertainty}
\leanok
\lean{Tile.uncertainty}
\uses{monotone-cube-metrics,tile-range-support}
    Let ${\mathfrak p}_1, {\mathfrak p}_2\in {\mathfrak P}$ with
    $B({\mathrm{c}}({\mathfrak p}_1),5D^{{\mathrm{s}}({\mathfrak p}_1)}) \cap B({\mathrm{c}}({\mathfrak p}_2),5D^{{\mathrm{s}}({\mathfrak p}_2)}) \ne \emptyset$ and
${\mathrm{s}}({{\mathfrak p}_1})\leq {\mathrm{s}}({{\mathfrak p}_2})$. For each $x_1\in E({\mathfrak p}_1)$ and
$x_2\in E({\mathfrak p}_2)$ we have
\begin{equation}\label{tgeo}
  1+d_{{\mathfrak p}_1}({\mathcal{Q}}({\mathfrak p}_1), {\mathcal{Q}}({\mathfrak p}_2))\le
    2^{8a}(1 + d_{B(x_1, D^{{\mathrm{s}}({\mathfrak p}_1)})}({Q}(x_1),{Q}(x_2)))\, .
\end{equation}
\end{lemma}

