\leanok
Let $i\in \{1,2\}$.
By Definition \eqref{defineep} of $E$,
we have ${Q}(x_i)\in {\Omega}({\mathfrak p}_i)$
With \eqref{eq-freq-comp-ball} we then conclude
\begin{equation}\label{dponetwo}
    d_{{\mathfrak p}_i}({Q}(x_i),{\mathcal{Q}}({\mathfrak p}_i)) < 1\, .
\end{equation}
We have by the triangle inequality and \eqref{eq-vol-sp-cube} that ${\mathcal{I}}({\mathfrak p}_1) \subset B({\mathrm{c}}({\mathfrak p}_2),14D^{{\mathrm{s}}({\mathfrak p}_2)})$.
Thus, using again \eqref{eq-vol-sp-cube} and the doubling property \eqref{firstdb}
\begin{equation}\label{tgeo0.5}
    d_{{\mathfrak p}_1}({Q}(x_2), {\mathcal{Q}}({\mathfrak p}_2)) \le 2^{6a} d_{{\mathfrak p}_2}({Q}(x_2), {\mathcal{Q}}({\mathfrak p}_2)) \le 2^{6a}\,.
\end{equation}
By the triangle inequality, we obtain from \eqref{dponetwo} and
\eqref{tgeo0.5}
\begin{equation}\label{tgeo1}
     1+d_{{\mathfrak p}_1}({\mathcal{Q}}({\mathfrak p}_1), {\mathcal{Q}}({\mathfrak p}_2))\le 2 + 2^{6a} +d_{{\mathfrak p}_1}({Q}(x_1), {Q}(x_2))\, .
\end{equation}
As $x_1\in {\mathcal{I}}({\mathfrak p}_1)$ by Definition \eqref{defineep} of $E$, we have by the squeezing property \eqref{eq-vol-sp-cube}
\begin{equation}
    d(x_1,{\mathrm{c}}({\mathfrak p}_1))\le 4D^{{\mathrm{s}}({\mathfrak p}_1)}
\end{equation}
and thus by \eqref{eq-vol-sp-cube} again and the triangle inequality
\begin{equation}
    {\mathcal{I}}({\mathfrak p}_1)\subset B(x_1,8D^{{\mathrm{s}}({\mathfrak p}_1)})\, .
\end{equation}
We thus estimate the right-hand side of \eqref{tgeo1} with monotonicity \eqref{monotonedb} of the metrics $d_B$ by
\begin{equation}\label{tgeo1.5}
    \le 2 + 2^{6a} + d_{B(x_1,8D^{{\mathrm{s}}({\mathfrak p}_1)})}({Q}(x_1), {Q}(x_2))\, .
\end{equation}
This is further estimated by applying the doubling property \eqref{firstdb} three times by
\begin{equation}\label{tgeo2}
    \le 2 + 2^{6a} +2^{3a}d_{B_1(x_1, D^{{\mathrm{s}}({\mathfrak p}_1)})}({Q}(x_1), {Q}(x_2))\, .
\end{equation}
Now \eqref{tgeo} follows with $a\ge 4$.
\end{proof}

