\begin{proof}[Proof of \Cref{tile-correlation}]
    \leanok
    \proves{tile-correlation}
We begin with \eqref{eq-basic-TT*-est}.
By Lemma \ref{tile-range-support}, the left-hand side of \eqref{eq-basic-TT*-est} vanishes if
$B({\mathrm{c}}({\mathfrak p}'),5D^{{\mathrm{s}}({\mathfrak p}')}) \cap B({\mathrm{c}}({\mathfrak p}),5D^{{\mathrm{s}}({\mathfrak p})}) = \emptyset$.
Thus we can assume for the remainder of the proof that
\begin{equation}
        \label{intersec5B}
        B({\mathrm{c}}({\mathfrak p}'),5D^{{\mathrm{s}}({\mathfrak p}')}) \cap B({\mathrm{c}}({\mathfrak p}),5D^{{\mathrm{s}}({\mathfrak p})}) \neq \emptyset\,.
\end{equation}
We expand the left-hand side of \eqref{eq-basic-TT*-est} as
\begin{equation}\label{tstartstar}
\left|\int \int_{E({\mathfrak p}')} \overline{K_{{\mathrm{s}}({\mathfrak p}')}(x_1,y)}e(-{Q}(x_1)(y)+
    {Q}(x_1)(x_1))g(x_1)\, d\mu(x_1) \right.
\end{equation}
\begin{equation}\label{tstartstar'}
 \times \left.\int_{E({\mathfrak p})} {K_{{\mathrm{s}}({\mathfrak p})}(x_2,y)}e({Q}(x_2)(y)
    -{Q}(x_2)(x_2))\overline{g(x_2)}\, d\mu(x_2)\, d\mu(y)\right|\, .
\end{equation}
By Fubini and the triangle inequality and
the fact $|e({Q}(x_i)(x_i))|=1$ for $i=1,2$, we can estimate
\eqref{tstartstar} and \eqref{tstartstar'} from above by
\begin{equation}\label{eqa1}
    \int_{E({\mathfrak p}')} \int_{E({\mathfrak p})} {\bf I}(x_1, x_2)\, d\mu(x_1)d\mu(x_2)\,.
\end{equation}
with
\begin{equation}
    {\bf I}(x_1, x_2):=
    \left|\int
    e(-{Q}(x_1)(y)+{Q}(x_2)(y))\varphi_{x_1,x_2}(y)
    d\mu(y) \, g(x_1)g(x_2)\right|
\end{equation}


We estimate for fixed $x_1\in E({\mathfrak p}')$ and
$x_2\in E({\mathfrak p})$ the inner integral of \eqref{eqa1} with
\Cref{Holder-van-der-Corput}. The function
$\varphi:=\varphi_{x_1,x_2}$ satisfies the assumptions of
\Cref{Holder-van-der-Corput} with $z = x_1$ and $R = D^{s_1}$ by \Cref{correlation-kernel-bound}.
We obtain with $B':= B(x_1, D^{{\mathrm{s}}({\mathfrak p}')})$,
\begin{equation*}
 {\bf I}(x_1, x_2) \le 2^{8a} \mu(B') \|{\varphi}\|_{C^\tau(B')}
       (1 + d_{B'}({Q}(x_1),{Q}(x_2)))^{-1/(2a^2+a^3)}|g(x_1)g(x_2)|
\end{equation*}
\begin{equation}
\label{eqa1.5}
 \le \frac{2^{231a^3+8a}}{\mu(B(x_2, D^{{\mathrm{s}}({\mathfrak p})}))}
       (1 + d_{B'}({Q}(x_1),{Q}(x_2)))^{-1/(2a^2+a^3)}\,.
\end{equation}
Using \eqref{intersec5B}, \Cref{tile-uncertainty} and $a\ge 1$ estimates \eqref{eqa1.5} by
\begin{equation}\label{eqa2}
 \le \frac{2^{231a^3 + 8a + 1}}{\mu(B(x_2, D^{{\mathrm{s}}({\mathfrak p})}))}
       (1+d_{{\mathfrak p}'}({\mathcal{Q}}({\mathfrak p}'), {\mathcal{Q}}({\mathfrak p})))^{-1/(2a^2+a^3)}|g(x_1)g(x_2)|\,.
\end{equation}
As $x_2\in {\mathcal{I}}({\mathfrak p})$ by Definition \eqref{defineep} of $E$, we have by \eqref{eq-vol-sp-cube}
\begin{equation}
    \rho(x_2,{\mathrm{c}}({\mathfrak p})) < 4D^{{\mathrm{s}}({\mathfrak p})}
\end{equation}
and thus by \eqref{eq-vol-sp-cube} again and the triangle inequality
\begin{equation}
    {\mathcal{I}}({\mathfrak p})\subset B(x_2,8D^{{\mathrm{s}}({\mathfrak p})})\, .
\end{equation}
Using three iterations of the doubling property \eqref{doublingx} give
\begin{equation}
    \mu({\mathcal{I}}({\mathfrak p}))\le 2^{3a}\mu(B(x_2,D^{{\mathrm{s}}({\mathfrak p})}))\, .
\end{equation}
With $a\ge 4$ and \eqref{eqa2} we conclude \eqref{eq-basic-TT*-est}.


Now assume the left-hand side of \eqref{eq-basic-TT*-est} is not zero.
There is a $y\in X$ with
\begin{equation}
