\begin{lemma}[tile reach]\label{tile-reach}
\leanok
\lean{Antichain.tile_reach}
\uses{monotone-cube-metrics}
Let ${\vartheta}\in {\Theta}$ and $N\ge0$ be an integer.
Let ${\mathfrak p}, {\mathfrak p}'\in {\mathfrak P}$ with
\begin{equation}\label{eqassumedismfa}
    d_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}), {\vartheta}))\le 2^N\,
\end{equation}
\begin{equation}\label{eqassumedismfap}
    d_{{\mathfrak p}'}({\mathcal{Q}}({\mathfrak p}'), {\vartheta}))\le 2^N\, .
\end{equation}
Assume ${\mathcal{I}}({\mathfrak p})\subset {\mathcal{I}}({\mathfrak p}')$ and ${\mathrm{s}}({\mathfrak p})<{\mathrm{s}}({\mathfrak p}')$.
Then
\begin{equation}\label{lp'lp''}2^{N+2}{\mathfrak p}\lesssim 2^{N+2} {\mathfrak p}'\, .
\end{equation}
\end{lemma}

n31307.content:
\begin{proof}
\leanok
By \Cref{monotone-cube-metrics}, we have
\begin{equation}
     d_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}'),{\vartheta})
     \le d_{{\mathfrak p}'}({\mathcal{Q}}({\mathfrak p}'),{\vartheta})
     \le 2^{N} \, .
\end{equation}
Together with \eqref{eqassumedismfa} and the triangle inequality, we obtain
\begin{equation}\label{eqdistqpqp}
    d_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}'),{\mathcal{Q}}({\mathfrak p}))\le 2^{N+1} \, .
\end{equation}
Now assume
\begin{equation}
    {\vartheta}'\in B_{{\mathfrak p}'}({\mathcal{Q}}({\mathfrak p}'),2^{N+2}).
\end{equation}
By the doubling property \eqref{firstdb}, applied five times, we have
\begin{equation}\label{ageo1} d_{B({\mathrm{c}}({\mathfrak p}'),8D^{{\mathrm{s}}({\mathfrak p}')})}({\mathcal{Q}}({\mathfrak p}'),{\vartheta}') < 2^{5a+N+2}\, .
\end{equation}
We have by the squeezing property \eqref{eq-vol-sp-cube}
\begin{equation}
 {\mathrm{c}}({\mathfrak p})\in
B({\mathrm{c}}({\mathfrak p}'),4D^{{\mathrm{s}}({\mathfrak p}')})\, .
\end{equation}
Hence by the triangle inequality
\begin{equation}
 B({\mathrm{c}}({\mathfrak p}), 4D^{{\mathrm{s}}({\mathfrak p}')})
 \subseteq
B({\mathrm{c}}({\mathfrak p}'),8D^{{\mathrm{s}}({\mathfrak p}')})\, .
\end{equation}
Together with \eqref{ageo1} and monotonicity \eqref{monotonedb} of $d$
\begin{equation}
    d_{B({\mathrm{c}}({\mathfrak p}),4D^{{\mathrm{s}}({\mathfrak p}')})}({\mathcal{Q}}({\mathfrak p}'),{\vartheta}') < 2^{5a+N+2}\, .
\end{equation}
Using the doubling property \eqref{seconddb} $5a+2$ times gives
\begin{equation}
    d_{B({\mathrm{c}}({\mathfrak p}),2^{2-5a^2-2a}D^{{\mathrm{s}}({\mathfrak p}')})}({\mathcal{Q}}({\mathfrak p}'),{\vartheta}') < 2^{N}\, .
\end{equation}
Using ${\mathrm{s}}({\mathfrak p})<{\mathrm{s}}({\mathfrak p}')$ and $D=2^{100a^2}$ and $a\ge 4$ gives
\begin{equation}
    d_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}'),{\vartheta}') < 2^{N}\, .
\end{equation}
With the triangle inequality and \eqref{eqdistqpqp},
\begin{equation}
    d_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}),{\vartheta}') < 2^{N+2}\, .
\end{equation}
This shows
\begin{equation}
B_{{\mathfrak p}'}({\mathcal{Q}}({\mathfrak p}'),2^{N+2})\subset B_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}),2^{N+2})\, .
\end{equation}
This implies \eqref{lp'lp''} and completes the proof of the lemma.
\end{proof}

