\begin{lemma}[stack density]
\label{stack-density}
\leanok
\lean{Antichain.stack_density}
Let ${\vartheta}\in {\Theta}$, $N\ge 0$ and
$L\in \mathcal{D}$. Then
\begin{equation}\label{eqanti-1}
    \sum_{{\mathfrak p}\in\mathfrak{A}_{{\vartheta},N}:{\mathcal{I}}({\mathfrak p})=L}\mu(E({\mathfrak p})\cap G)\le 2^{a(N+5)}\dens_1(\mathfrak{A})\mu(L)\, .
\end{equation}
\end{lemma}

n31309.content:
\begin{proof}
\leanok
Let ${\vartheta},N,L$ be given and set
\begin{equation}
\mathfrak{A}':=\{{\mathfrak p}\in\mathfrak{A}_{{\vartheta},N}:{\mathcal{I}}({\mathfrak p})=L\}\, .
\end{equation}
Let
${\mathfrak p}\in\mathfrak{A}'$.
We have
by Definition \eqref{definedens1}
using $\lambda=2$ and the squeezing property \eqref{eq-freq-comp-ball}
\begin{equation}\label{eqanti-3}
\mu(E({\mathfrak p})\cap G)\le \mu(E_2(2, {\mathfrak p}))\le 2^{a}\dens_1(\mathfrak{A}')\mu(L)\, .
\end{equation}
By the covering property \eqref{thirddb}, applied $N+4$ times, there is a collection ${\Theta}'$ of at most $2^{a(N+4)}$
elements such that
\begin{equation}\label{eqanti-4}
    B_{{\mathfrak p}}({\vartheta}, 2^{N+1})\subset \bigcup_{{\vartheta}'\in {\Theta}'}
    B_{{\mathfrak p}}({\vartheta}', 0.2)\, .
\end{equation}
As each ${\mathcal{Q}}({\mathfrak p}')$ with ${\mathfrak p}'\in \mathfrak{A}'$
is contained in the left-hand-side
of \eqref{eqanti-4}
by definition (because ${\mathcal{I}}({\mathfrak p}') = {\mathcal{I}}({\mathfrak p}))$, it is in at least one $B_{{\mathfrak p}}({\vartheta}', 0.2)$
with ${\vartheta}'\in {\Theta}'$.


For two different ${\mathfrak p}',{\mathfrak p}''\in \mathfrak{A}'$, we have by
\eqref{eq-dis-freq-cover} that
${\Omega}({\mathfrak p}')$ and ${\Omega}({\mathfrak p}'')$ are disjoint and thus by the squeezing property \eqref{eq-freq-comp-ball} we have for every ${\vartheta}'\in {\Theta}'$
\begin{equation}
    {\vartheta}'\not \in B_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}'), 0.2)\cap
B_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak p}''), 0.2)\, .
\end{equation}
Hence at most one of ${\mathcal{Q}}({\mathfrak p}')$
and ${\mathcal{Q}}({\mathfrak p}'')$ is in
$B_{{\mathfrak p}}({\vartheta}', 0.2)$.
It follows that there are at most $2^{a(N+4)}$ elements in
$\mathfrak{A}'$. Adding \eqref{eqanti-3} over $\mathfrak{A}'$ proves
\eqref{eqanti-1}.
\end{proof}

