\begin{lemma}[local antichain density]\label{local-antichain-density}
\leanok
\lean{Antichain.local_antichain_density, Antichain.Ep_inter_G_inter_Ip'_subset_E2}
\uses{tile-disjointness,tile-reach}
Let ${\vartheta}\in{\Theta}$ and {$N$} be
an integer. Let ${\mathfrak p}_{{\vartheta}}$ be a tile with ${\vartheta}\in B_{{\mathfrak p}_{{\vartheta}}}({\mathcal{Q}}({\mathfrak p}_{{\vartheta}}), 2^{N+1})$.
Then we have
\begin{equation}\label{eqanti-0.5}
    \sum_{{\mathfrak p}\in\mathfrak{A}_{{\vartheta},N}: {\mathrm{s}}({\mathfrak p}_{{\vartheta}})<{\mathrm{s}}({\mathfrak p})}\mu(E({\mathfrak p})\cap G \cap {\mathcal{I}}({\mathfrak p}_{{\vartheta}}))
    \le \mu (E_2(2^{N+3},{\mathfrak p}_{{\vartheta}}))
 \, .
\end{equation}



\end{lemma}

n31311.content:
\begin{proof}
\leanok

Let ${\mathfrak p}$ be any tile in $\mathfrak{A}_{{\vartheta},N}$ with ${\mathrm{s}}({\mathfrak p}_{{\vartheta}})<{\mathrm{s}}({\mathfrak p})$. By definition of
$E$, the tile contributes zero to the sum on the left-hand side of \eqref{eqanti-0.5} unless
 ${\mathcal{I}}({\mathfrak p})\cap {\mathcal{I}}({\mathfrak p}_{{\vartheta}}) \neq \emptyset$, which we may assume. With ${\mathrm{s}}({\mathfrak p}_{{\vartheta}})<{\mathrm{s}}({\mathfrak p})$
and the dyadic property
\eqref{dyadicproperty} we conclude ${\mathcal{I}}({\mathfrak p}_{{\vartheta}})\subset {\mathcal{I}}({\mathfrak p})$.
We conclude from ${\mathfrak p}\in \mathfrak{A}_{{\vartheta},N}$ that
\begin{equation}
    {\vartheta}\in B_{\mathfrak p}({\mathcal{Q}}({\mathfrak p}), 2^{N+1})\, .
\end{equation}
With \Cref{tile-reach} and the assumption on ${\mathfrak p}_{\vartheta}$, we conclude
\begin{equation}
    2^{N+3}{\mathfrak p}_{{\vartheta}} \lesssim 2^{N+3}{\mathfrak p}\, .
\end{equation}
By Definition \eqref{definee2} of $E_2$, we conclude
\begin{equation}
    E({\mathfrak p})\cap G \cap {\mathcal{I}}({\mathfrak p}_{{\vartheta}}) \subset E_2(2^{N+3},{\mathfrak p}_{{\vartheta}})\, .
\end{equation}
Using disjointedness of the various $E({\mathfrak p})$ with ${\mathfrak p}\in \mathfrak{A}$ by \Cref{tile-disjointness}, we obtain \eqref{eqanti-0.5}.
This proves the lemma.
\end{proof}

