\end{equation}
\begin{equation}
    = 2^{-pN/(2a^2+a^3)} \sum_{{\mathfrak p}\in\mathfrak{A}_{{\vartheta},N}}\mu(E({\mathfrak p})\cap G)
\end{equation}

Using \Cref{global-antichain-density}, we estimate the last display by
\begin{equation}\label{eqanti21}
    \le 2^{-pN/(2a^2+a^3)+101a^3+Na}\dens_1(\mathfrak{A})\mu\left(\cup_{{\mathfrak p}\in\mathfrak{A}}{\mathcal{I}}({\mathfrak p})\right)
\end{equation}
Using that $a\ge 4$ and since $p = 4a^4$, we have
$$
    pN/(2a^2+a^3)\ge 4a^4N/(3a^3) \ge Na+N\, .
$$
Hence we have for \eqref{eqanti21} the upper bound
$$
    \le 2^{101a^3-N}\dens_1(\mathfrak{A})\mu\left(\cup_{{\mathfrak p}\in\mathfrak{A}}{\mathcal{I}}({\mathfrak p})\right)\, .
$$
Taking the $p$-th root and summing over $N\ge 0$ gives for \eqref{eqanti23} the upper bound
$$
    \le \left(\sum_{N\ge 0} 2^{-N/p}\right)2^{101a^3/p}\dens_1(\mathfrak{A})^{{\frac{1}{p}}}\mu\left(\cup_{{\mathfrak p}\in\mathfrak{A}}{\mathcal{I}}({\mathfrak p})\right)^{{\frac{1}{p}}}
$$
$$
    = \left(1-2^{-1/p}\right)^{-1} 2^{101a^3/p} \dens_1(\mathfrak{A})^{\frac 1p}\mu\left(\cup_{{\mathfrak p}\in\mathfrak{A}}{\mathcal{I}}({\mathfrak p})\right)^{\frac 1p}\, .
$$
Using that $p = 4a^4$ and $a \ge 4$, this proves the lemma.
\end{proof}

