n31343.content:
\begin{lemma}[adjoint tree estimate]
    \label{adjoint-tree-estimate}
    \leanok
    \lean{TileStructure.Forest.adjoint_tree_estimate, TileStructure.Forest.indicator_adjoint_tree_estimate}
    \uses{densities-tree-bound}
    For all bounded $g$ supported on $G$ we have that
    $$
        \left\| \sum_{{\mathfrak p}\in {\mathfrak T}({\mathfrak u})} T_{{\mathfrak p}}^* g\right\|_2 \le 2^{181a^3} \dens_1({\mathfrak T}({\mathfrak u}))^{1/2} \|g\|_2\,,
    $$
    $$
        \left\| \mathbf{1}_F \sum_{{\mathfrak p}\in {\mathfrak T}({\mathfrak u})} T_{{\mathfrak p}}^* g\right\|_2 \le 2^{282a^3} \dens_1({\mathfrak T}({\mathfrak u}))^{1/2} \dens_2({\mathfrak T}({\mathfrak u}))^{1/2} \|g\|_2\,.
    $$
\end{lemma}

n31344.content:
\begin{proof}
    \leanok
    By \Cref{densities-tree-bound}, we have for all bounded $f$ and $g$ with $|g| \le \mathbf{1}_G$ that
    $$
        \left| \int_X \overline{\sum_{{\mathfrak p}\in {\mathfrak T}({\mathfrak u})} T_{{\mathfrak p}}^* g} f \,\mathrm{d}\mu \right| = \left| \int_X \overline{g} \sum_{{\mathfrak p}\in {\mathfrak T}({\mathfrak u})} T_{{\mathfrak p}} f \,\mathrm{d}\mu \right|
    $$
    \begin{equation}
        \label{eq-adjoint-bound}
        \le 2^{181a^3} \dens_1({\mathfrak T}({\mathfrak u}))^{1/2} \|g\|_2 \|f\|_2\,.
    \end{equation}
    Let $f = \sum_{{\mathfrak p}\in {\mathfrak T}({\mathfrak u})} T_{{\mathfrak p}}^* g$. Since $|g| \le \mathbf{1}_G$, $f$ is bounded and has bounded support. In particular $\|f\|_2 < \infty$. Dividing \eqref{eq-adjoint-bound} by $\|f\|_2$ completes the proof.

    The proof of the second part is similar with $f = \mathbf{1}_F \sum_{{\mathfrak p}\in {\mathfrak T}({\mathfrak u})} T_{{\mathfrak p}}^* g$.
\end{proof}

