\begin{lemma}[correlation separated trees]
    \label{correlation-separated-trees}
    \leanok
    \lean{TileStructure.Forest.correlation_separated_trees}
    \uses{correlation-distant-tree-parts,correlation-near-tree-parts}
    For any ${\mathfrak u}_1 \ne {\mathfrak u}_2 \in {\mathfrak U}$ and all bounded $g_1, g_2$ with bounded support, we have
    \begin{equation}
        \label{eq-lhs-sep-tree}
        \left| \int_X \sum_{{\mathfrak p}_1 \in {\mathfrak T}({\mathfrak u}_1)} \sum_{{\mathfrak p}_2 \in {\mathfrak T}({\mathfrak u}_2)} T^*_{{\mathfrak p}_1}g_1 \overline{T^*_{{\mathfrak p}_2}g_2 }\,\mathrm{d}\mu \right|
    \end{equation}
    \begin{equation}
        \label{eq-rhs-sep-tree}
        \le 2^{512a^3-4n} \prod_{j =1}^2 \| S_{2, {\mathfrak u}_j} g_j\|_{L^2({\mathcal{I}}({\mathfrak u}_1) \cap {\mathcal{I}}({\mathfrak u}_2))}\,.
    \end{equation}
\end{lemma}

n31348.content:
\begin{proof}[Proof of \Cref{correlation-separated-trees}]
    \leanok
    \proves{correlation-separated-trees}
    By \Cref{adjoint-tile-support} and \eqref{dyadicproperty}, the left hand side \eqref{eq-lhs-sep-tree} is $0$ unless ${\mathcal{I}}({\mathfrak u}_1) \subset {\mathcal{I}}({\mathfrak u}_2)$ or ${\mathcal{I}}({\mathfrak u}_2) \subset {\mathcal{I}}({\mathfrak u}_1)$. Without loss of generality we assume that ${\mathcal{I}}({\mathfrak u}_1) \subset {\mathcal{I}}({\mathfrak u}_2)$.

    Define
    \begin{equation}
        \label{def-Tree-S-set}
         \mathfrak{S} := \{{\mathfrak p}\in {\mathfrak T}({\mathfrak u}_1) \cup {\mathfrak T}({\mathfrak u}_2) \ : \ d_{{\mathfrak p}}({\mathcal{Q}}({\mathfrak u}_1), {\mathcal{Q}}({\mathfrak u}_2)) \ge 2^{Zn/2}\,\}.
    \end{equation}
    \Cref{correlation-separated-trees} follows by combining the definition \eqref{defineZ} of $Z$ with the following two lemmas.
\end{proof}

