n31356.content:
\begin{lemma}[moderate scale change]
        \label{moderate-scale-change}
        \leanok
        \lean{TileStructure.Forest.moderate_scale_change}

        If $J, J' \in \mathcal{J'}$ with
        $$
            B(J) \cap B(J') \ne \emptyset\,,
        $$
        then $|s(J) - s(J')| \le 1$.
    \end{lemma}

n31358.content:
\begin{proof}[Proof of \Cref{moderate-scale-change}]
        \leanok
        \proves{moderate-scale-change}
        Suppose that $s(J') < s(J) - 1$. Then $s(J) > -S$. Thus, by the definition of $\mathcal{J}'$ there exists no ${\mathfrak p}\in \mathfrak{S}$ with
      \begin{equation}
            \label{eq-tile-incl-1}
            {\mathcal{I}}({\mathfrak p}) \subset B(c(J), 100D^{s(J) + 1})\,.
        \end{equation}
        Since $s(J') < s(J)$, there exists a cube $J'' \in \mathcal{D}$ with $J \subset J''$ and $s(J'') = s(J') + 1$. By the definition of $\mathcal{J}'$, there exists a tile ${\mathfrak p}\in \mathfrak{S}$ with
      \begin{equation}
            \label{tile-incl-2}
            {\mathcal{I}}({\mathfrak p}) \subset B(c(J''), 100 D^{s(J')+2})\,.
        \end{equation}
        But by the triangle inequality and \eqref{defineD}, we have
        $$
            B(c(J''), 100 D^{s(J')+2}) \subset B(c(J), 100D^{s(J) + 1})\,,
        $$
        which contradicts \eqref{eq-tile-incl-1} and \eqref{tile-incl-2}.
    \end{proof}

n31359.content:
\begin{lemma}[Holder correlation tree]
