\begin{proof}[Proof of \Cref{Holder-correlation-tree}]
        \leanok
        \proves{Holder-correlation-tree}
        Let $P$ be the product on the right hand side of \eqref{hHolder}, and $h_J$ be as defined in \eqref{def-hj}.
        By \eqref{eq-pao-2} and \Cref{adjoint-tile-support}, the function $h_J$ is supported in $B'(J) \cap {\mathcal{I}}({\mathfrak u}_1)$.
        By \eqref{eq-pao-2}, \Cref{global-tree-control-1} and \Cref{global-tree-control-2}, we have for all $y \in B'(J)$:
        $$
            |h_J(y)| \le 2^{257a^3+4a+3} P\,.
        $$
        We have by the triangle inequality
        \begin{align}
            &|h_J(y) - h_J(y')|\nonumber\\
            \label{eq-h-Lip-1}
            &\le |\chi_J(y) - \chi_J(y')| |T_{{\mathfrak T}({\mathfrak u}_1)}^* g_1(y)| |T_{{\mathfrak T}({\mathfrak u}_2) \cap \mathfrak{S}}^* g_2(y)|\\
            \label{eq-h-Lip-2}
            & + |\chi_J(y')| |e({\mathcal{Q}}({\mathfrak u}_1)(y)) T_{{\mathfrak T}({\mathfrak u}_1)}^* g_1(y) - e({\mathcal{Q}}({\mathfrak u}_1)(y')) T_{{\mathfrak T}({\mathfrak u}_1)}^* g_1(y')| |T_{{\mathfrak T}({\mathfrak u}_2) \cap \mathfrak{S}}^* g_2(y)|\\
            \label{eq-h-Lip-3}
            & + |\chi_J(y')| |T_{{\mathfrak T}({\mathfrak u}_1)}^* g_1(y')| |e({\mathcal{Q}}({\mathfrak u}_2)(y)) T_{{\mathfrak T}({\mathfrak u}_2) \cap \mathfrak{S}}^* g_2(y) - e({\mathcal{Q}}({\mathfrak u}_2)(y')) T_{{\mathfrak T}({\mathfrak u}_2) \cap \mathfrak{S}}^* g_2(y')|\,.
        \end{align}

        As $h_J$ is supported in ${\mathcal{I}}({\mathfrak u}_1)$, we can assume without loss of generality that $y' \in {\mathcal{I}}({\mathfrak u}_1)$.
        If $y \notin {\mathcal{I}}({\mathfrak u}_1)$, then \eqref{eq-h-Lip-1} vanishes. If $y \in {\mathcal{I}}({\mathfrak u}_1)$ then we have by \eqref{eq-pao-3}, \Cref{global-tree-control-1} and \Cref{global-tree-control-2}
        % C7_5_2       C7_5_9s           C7_5_10
        % 2^{226a^3} * 2^{151a^3+4a+3} * 2^{151a^3+4a+4}
        % 2^{528a^3+8a+7}
        $$
            \eqref{eq-h-Lip-1} \le 2^{484a^3+4a+3} \frac{\rho(y,y')}{D^{s(J)}} P\,,
        $$
        where $P$ denotes the product on the right hand side of \eqref{hHolder}.

        By \eqref{eq-pao-2}, \Cref{global-tree-control-1} and \Cref{global-tree-control-2}, we have
        % C7_5_9d           C7_5_10
        % 2^{151a^3+4a+1} * 2^{151a^3+4a+4}
        % 2^{302a^3+8a+5}
        $$
            \eqref{eq-h-Lip-2} \le 2^{257a^3+4a+1} \left(\frac{\rho(y,y')}{D^{s(J)}}\right)^{1/a} P\,.
        $$

        By \eqref{eq-pao-2}, and twice \Cref{global-tree-control-1}, we have
        % C7_5_9s           C7_5_9d
        % 2^{151a^3+4a+3} * 2^{151a^3+4a+1}
        % 2^{302a^3+8a+4}
        $$
            \eqref{eq-h-Lip-3} \le 2^{256a^3+8a+5} \left(\frac{\rho(y,y')}{D^{s(J)}}\right)^{1/a} P\,.
        $$
        Using that $\rho(y,y') \le 32D^{s(J)}$ and $a \ge 4$, the lemma follows.
    \end{proof}

