   =p_2\int _0^{\infty}
    \lambda^{p_2-1} \mu(\{x: M_{\mathcal{B}}u(x)\ge \lambda\}) d\lambda\,
\end{equation}
\begin{equation} \label{eqbesi11}
   =2^{p_2} p_2\int _0^{\infty}
    \lambda^{p_2-1} \mu(\{x: M_{\mathcal{B}}u(x)\ge 2\lambda\}) d\lambda\, .
\end{equation}
