=\int_{B'} u (y)\, d\mu(y)-
\int_{B'} (u-u_\lambda) (y) d\mu(y)\,
\end{equation}
\begin{equation}
\ge 2\lambda \mu({B'})-
\int_{B'} (u-u_\lambda) (y) d\mu(y)\, .
