n31427.content:
\begin{lemma}[Disjoint family countable]
    \leanok
    \lean{Pairwise.countable_of_isOpen_disjoint}
    \label{disjoint-family-countable}
    In a doubling metric measure space $(X,\rho,\mu, a)$, every disjoint family of balls $B_j = B(x_j, r_j)$, $j\in J$, is countable.
\end{lemma}

n31428.content:
\begin{proof}
    \leanok
    Choose an arbitrary $x\in X$ as reference point. For $q, Q\in{\mathbb{Q}}_+$, let $J_{q,Q}$ denote the set of all $j\in J$ such that $B_j\subset B(x, Q)$ and $r_j \ge q$. It suffices to show that all the $J_{q,Q}$ are finite.
    Indeed, for all $j\in J_{q,Q}$,
    \begin{equation*}
        \mu(B(x, Q)) \le \mu(B(x_j, 2Q)) = \mu(B(x_j, \frac{2 Q}{r_j} r_j))
        \le 2^{a\log_2{\lceil \frac{2 Q}{r_j}\rceil}} \mu(B_j).
    \end{equation*}
    Since the $B_j$ are disjoint,
    \begin{equation}
        |J_{q,Q}| \mu(B(x, Q)) \le 2^{a\log_2{\lceil\frac{2Q}{q}\rceil}} \sum_{j\in J_{q,Q}} \mu(B_j) \le 2^{a\log_2{\lceil\frac{2Q}{q}\rceil}} \mu(B(x,Q))
    \end{equation}
    and hence $|J_{q,Q}| \le 2^{a\log_2{\lceil\frac{2Q}{q}\rceil}}$.
\end{proof}

n31429.content:
\begin{lemma}[Ball covering]
    \label{ball-covering}
    \leanok
    \lean{ball_covering}
    \uses{disjoint-family-countable}
    Given an open set $O\ne X$, there exists a countable family of balls $B_j = B(x_j, r_j)$ such that
    \begin{equation}
        \label{balls-disjoint}
        B_j \cap B_{j'} = \emptyset \quad \text{ for } j \ne j',
    \end{equation}
    and
    \begin{equation}
        \label{balls-covering}
        \bigcup_j B_{3,j} = O,
    \end{equation}
    and
    \begin{equation}
        \label{enlarged-balls-intersect-complement}
        B_{7,j} \cap (X \setminus O) \ne \emptyset \quad \text{ for all } j
    \end{equation}
    and we have the bounded intersection property that each $x\in O$ is contained in at most $2^{6a}$ of the $B_{3,j}$.
\end{lemma}

n31430.content:
\begin{proof}
\leanok
Define for $x\in O$,
\begin{equation}
    \delta(x):= \sup \{\delta\in{\mathbb{R}}: B(x,\delta)\subset O\}.
\end{equation}
Since $O$ is open, and $O\ne X$, we have
\begin{equation}
    0 < \delta(x) < \infty \,.
\end{equation}
Using Zorn's Lemma, we select a maximal disjoint subfamily of $\{B(x,\frac{\delta(x)}{6}) : x \in O\}$.
We obtain a (by \Cref{disjoint-family-countable} countable) family of balls $B_j = B(x_j, \frac{\delta(x_j)}{6}), j \in J$ such that \eqref{balls-disjoint}, \eqref{enlarged-balls-intersect-complement}, and $\bigcup_j B_{3,j} \subset O$ are also immediate. For the other inclusion, first observe that for $x,y\in X$,  if $B(x,\frac{\delta(x)}{6}) \cap B(y,\frac{\delta(y)}{6}) \ne \emptyset$, then
\begin{equation*}
    \delta(x) \le \rho(x,y) + \delta(y) \le (\frac{\delta(x)}{6} + \frac{\delta(y)}{6}) + \delta(y) = \frac{\delta(x)}{6} + \frac{7\delta(y)}{6},
\end{equation*}
so
\begin{equation}
    \label{control-distance-growth}
    \delta(x) \le 2 \delta(y).
\end{equation}
Now let $z\in O$. By maximality, there exists some $j\in J$ with $B(z,\frac{\delta(z)}{6}) \cap B_j \ne \emptyset$. By \eqref{control-distance-growth},
\begin{equation*}
    \rho(z,x_j)< \frac{\delta(z)}{6} + \frac{\delta(x_j)}{6} \le \frac{3\delta(x_j)}{6} = 3r_j
\end{equation*}
and thus $z\in B_{3,j}$.

We now turn to the bounded intersection property. Assume that for some $j_1,\dots,j_N$,
\begin{equation}
    z\in \bigcap_{k=1}^N B_{3,j_k}.
\end{equation}
Similarly as above, observe for $1\le k \le N$,
\begin{equation}
    \label{control-distance-growth-b}
    \delta(z) \le \rho(z,x_{j_k}) + \delta(x_{j_k}) \le \frac{\delta(x_{j_k})}{2} + \delta(x_{j_k}) = \frac{3\delta(x_{j_k})}{2}
\end{equation}
and
\begin{equation*}
    \delta(x_{j_k}) \le \rho(x_{j_k},z) + \delta(z) \le \frac{\delta(x_{j_k})}{2} + \delta(z),
\end{equation*}
so
\begin{equation}
    \label{control-distance-growth-c}
    \delta(x_{j_k}) \le 2 \delta(z).
\end{equation}

By \eqref{control-distance-growth-b} and \eqref{control-distance-growth-c}, for all $1\le k \le N$, $B(z,\frac{\delta(z)}{6}) \subset B(x_{j_k}, 5r_{j_k})$ and $B_{j_k} \subset B(z,\frac{8\delta(z)}{6})$. Using this and \eqref{balls-disjoint}, we obtain
\begin{align}
    N \mu(B(z,\frac{\delta(z)}{6})) &\le \sum_{k=1}^N \mu(B(x_{j_k}, 5r_j)) \le 2^{3a} \sum_{k=1}^N \mu(B_{j_k}) \\
    &= 2^{3a} \mu(\bigcup_{k=1}^N B_{j_k}) \le 2^{3a} \mu(B(z,\frac{8\delta(z)}{6})) \le 2^{6a} \mu(B(z,\frac{\delta(z)}{6}))
\end{align}
and conclude $N\le 2^{6a}$.
\end{proof}

n31431.content:
\begin{lemma}[Calderon Zygmund decomposition]
    \label{Calderon-Zygmund-decomposition}
    \leanok
    \lean{encard_czBall3_le, tsum_czRemainder', aemeasurable_czApproximation, czApproximation_add_czRemainder, enorm_czApproximation_le, enorm_czApproximation_le_infinite, eLpNorm_czApproximation_le, support_czRemainder'_subset, integral_czRemainder', integral_czRemainder, eLpNorm_czRemainder'_le, eLpNorm_czRemainder_le, tsum_volume_czBall3_le, volume_univ_le, tsum_eLpNorm_czRemainder'_le, tsum_eLpNorm_czRemainder_le}
    \uses{ball-covering,Lebesgue-differentiation,maximal-theorem}
    Let $f$ be a bounded, a.e. measurable function supported on a set of finite measure and let $\alpha>\frac{1}{\mu(X)}\int |f|\,d\mu$.
    Then there exists a bounded a.e. measurable function $g$ supported on a set of finite measure, a countable family of balls $B_{3,j}$ (where we allow $B_{3,1} = X$ in the special case that $\mu(X)<\infty$)
    % Do we actually need this parenthetical?
    such that each $x\in X$ is contained in at most $2^{6a}$ of the $B_{3,j}$, and a countable family of a.e. measurable functions $\{b_j\}_{j\in J}$ such that for all $x \in X$
    \begin{equation}
       \label{eq-gb-dec}
       f(x)= g(x) + \sum_{j} b_j(x)
    \end{equation}
    and such that the following holds. For almost every $x\in X$,
    \begin{equation}
        \label{eq-g-max}
       |g(x)|\leq 2^{3a} \alpha\,.
    \end{equation}
    We have
    \begin{equation}
        \label{eq-g-L1-norm}
        \int |g(y)|\, d\mu(y)\leq \int |f(y)|\, d\mu(y).
    \end{equation}
    For every $j$
    \begin{equation}
        \label{eq-supp-bj}
        \operatorname{supp} b_j \subset B_{3,j}\,.
    \end{equation}
    For every $j$
    \begin{equation}
        \label{eq-bad-mean-zero}
        \int_{B_{3,j}} b_j(x)\, d\mu(x)=0,
    \end{equation}
    and
     \begin{equation}
        \label{eq-bj-L1}
        \int_{B_{3,j}} |b_j(x)|\, d\mu(x) \leq 2^{2a+1} \alpha \mu(B_{3,j}).
    \end{equation}
    We have
    \begin{equation}
        \label{eq-bset-length-sum}
        \sum_j \mu(B_{3,j})\leq \frac{2^{4a}}{\alpha}\int |f(y)|\, d\mu(y)
    \end{equation}
    and
    \begin{equation}
    \label{eq-b-L1}
    \sum_{j}\int_{B_{3,j}} |b_j(y)|\, d\mu(y)\leq 2 \int |f(y)|\, d\mu(y)\,.
    \end{equation}
\end{lemma}

n31432.content:
\begin{proof}
\leanok
Let $E_\alpha:=\{x\in X: Mf(x)>\alpha\}$.
Then $E_\alpha$ is open. Assume first that $E_\alpha \ne X$. We apply \Cref{ball-covering} with $O=E_\alpha$ to obtain the family $B_j, j\in J,$. Without loss of generality, we can assume $J={\mathbb{N}}$. Define inductively
\begin{equation}
    Q_j := B_{3,j} \setminus \left(\bigcup_{i<j} Q_i \cup \bigcup_{i>j} B_i \right).
\end{equation}
Then $B_j\subset Q_j\subset B_{3,j}$, the $Q_j$ are pairwise disjoint and $\bigcup_j Q_j = E_\alpha$.
Define
\begin{equation}
    \label{eq-g-def}
    g(x):=\begin{cases}
     f(x), & x\in X\setminus E_\alpha,\\
     \frac{1}{\mu(Q_j)}\int_{Q_j} f(y)\, d\mu(y), &x\in Q_j,
    \end{cases}
\end{equation}
and, for each $j$,
\begin{equation}
    b_j(x):= \mathbf{1}_{Q_j}(x) \left(f(x)-\frac{1}{\mu(Q_j)}\int_{Q_j} f(y)\, d\mu(y) \right).
\end{equation}
Then \eqref{eq-gb-dec}, \eqref{eq-supp-bj} and \eqref{eq-bad-mean-zero} are true by construction.
Boundedness of $g$ is immediate from the definition, as is the fact that $\supp g$ is contained within
$\supp f \cup \bigcup_j Q_j$. Now the fact that $\supp g$ has finite measure follows from
$\bigcup_j Q_j = E_\alpha$ and \eqref{eq-hlm-2}.

For \eqref{eq-g-max}, we first do the case $x\in X\setminus E_\alpha$. By definition of $Mf$,
\begin{equation}
    \frac{1}{\mu(B)}\int_B |f(y)|\,d\mu(y) \le \alpha
\end{equation}
for every ball $B\subset X$ with $x\in B$. It follows by \Cref{Lebesgue-differentiation} that for almost every $x\in X\setminus E_\alpha$, $|f(x)|\le \alpha$.
In the case $x\in E_\alpha$, there exists some $j\in J$ with $x\in Q_j$ and we have that
\begin{equation}
    \label{large-ball-estimate}
    \frac{1}{\mu(B_{7,j})} \int_{B_{7,j}} |f(y)| \,d\mu(y) \le \alpha
\end{equation}
because $B_{7,j}\cap (X\setminus E_\alpha) \ne \emptyset$. We get
\begin{equation}
    |g(x)| \le \frac{1}{\mu(Q_j)}\int_{Q_j} |f(y)|\, d\mu(y) \le \frac{1}{\mu(B_j)}\int_{B_{7,j}} |f(y)| \, d\mu(y) \le 2^{3a}\alpha .
\end{equation}

To prove \eqref{eq-g-L1-norm}, we estimate
\begin{align*}
    \int |g(z)|\, d\mu(z) &\le \int_{X\setminus E_\alpha} |f(z)|\, d\mu(z) + \sum_{j} \int_{Q_j}\frac{1}{\mu(Q_j)}\int_{Q_j}|f(y)|\, d\mu(y)\,d\mu(z) \\
    &= \int |f(z)|\,d\mu(z).
\end{align*}
Using the triangle inequality, we have that
\begin{align}
    \label{eq-bj-int}
    \int_{B_{3,j}} |b_j(y)|\, dy &\le \int_{Q_j} |f(y)|\, d\mu(y) + \int_{Q_j} \frac{1}{\mu(Q_j)}\int_{Q_j} |f(x)|\, d\mu(x)\, d\mu(y) \\
    &= 2 \int_{Q_j} |f(y)|\, dy.
\end{align}
With \eqref{large-ball-estimate}, we estimate further
\begin{equation}
    \le 2 \int_{B_{7,j}} |f(y)|\, dy \le 2\mu(B_{7,j})\alpha \le 2^{2a+1} \alpha \mu(B_{3,j})
\end{equation}
to obtain \eqref{eq-bj-L1}.
Further, summing up \eqref{eq-bj-int} in $j$ yields \eqref{eq-b-L1}.
At last, we estimate with \Cref{maximal-theorem}
\begin{equation}
    \sum_j \mu(B_{3,j}) \le 2^{2a} \sum_j \mu(B_j) \le 2^{2a} \mu(E_\alpha) \le \frac{2^{4a}}{\alpha}\int |f(y)|\, d\mu(y),
\end{equation}
proving \eqref{eq-bset-length-sum}.

Assume now that $E_\alpha = X$. It follows from \Cref{maximal-theorem} that then $\mu(X)<\infty$.
Define
\begin{equation*}
    g := \frac{1}{\mu(X)} \int |f(y)|\,d\mu(y)
\end{equation*}
and
\begin{equation*}
    b_1 := f - g.
\end{equation*}
Then $f = g + b_1$ and $\supp b_1 \subset B_{3,1}:=X$ and \eqref{eq-gb-dec}, \eqref{eq-g-L1-norm}, \eqref{eq-supp-bj}, \eqref{eq-bad-mean-zero} all hold immediately. By assumption, $\alpha>\frac{1}{\mu(X)}\int |f|\,d\mu = g$, so \eqref{eq-g-max} holds.
We also have, using the definitions and the same assumption,
\begin{equation}
    \int |b_1(y)|\, d\mu(y) \le 2 \int |f(y)|\,d\mu(y) \le 2\alpha\mu(X),
\end{equation}
which verifies both \eqref{eq-b-L1} and \eqref{eq-bj-L1}.
Finally, by \Cref{maximal-theorem},
\begin{equation*}
    \mu(X) \le \frac{2^{2a}}{\alpha} \int |f(y)|\,d\mu(y),
\end{equation*}
which shows \eqref{eq-bset-length-sum}.
\end{proof}

n31434.content:
\begin{proof}
    \leanok
    We estimate using monotonicity of the integral
\begin{equation*}
     \mu\left(\{x\in X: |T_r g(x)|>{\alpha}/2\}\right)\leq \frac{4}{\alpha^2} \int |T_r g(y)|^2\, d\mu(y).
\end{equation*}
Using \eqref{eq-strong-2-2-assumption} followed by \eqref{eq-g-max} and \eqref{eq-g-L1-norm}, we estimate the right hand side above by
\begin{equation}
    \label{eq-Hr-g}
    \leq \frac{4\cdot 2^{2a^3}}{\alpha^2} \int |g(y)|^2\, d\mu(y)\leq \frac{2^{2a^3+3a+2}c}{\alpha} \int |g(y)|\, dy \le \frac{2^{2a^3+3a+2}c}{\alpha} \int |f(y)|\, d\mu(y).
\end{equation}
\end{proof}

n31435.content:
\begin{lemma}[Estimate bad partial]
    \label{estimate-bad-partial}
    \leanok
    \lean{estimate_bad_partial}
    \uses{Calderon-Zygmund-decomposition}
    Let $x\in X\setminus\Omega$. Then
    \begin{equation*}
        |T_rb(x)| \le 3F(x)+\alpha/8,
    \end{equation*}
    where
    \begin{equation*}
        F(x) := 2^{a^3+2a+1} c\alpha \sum_{j\in J} \left(\frac{3r_j}{\rho(x,x_j)}\right)^{\frac{1}{a}}\frac{\mu(B_{3,j})}{V(x,x_j)}.
    \end{equation*}
\end{lemma}

n31436.content:
\begin{proof}
\leanok
We decompose the index set $J$ into the following disjoint sets:
\begin{align*}
    \mathcal{J}_1(x)&:=\{j\,: r+3r_j \le \rho(x,x_j) \},\\
    \mathcal{J}_2(x)&:=\{j\,: r-3r_j \le \rho(x,x_j) < r+3r_j\},\\
    \mathcal{J}_3(x)&:=\{j\,: \rho(x,x_j) < r-3r_j\}.
\end{align*}
Then
\begin{alignat}{3}
    \label{eq-b-dec-1}
    |T_r b(x)|\le&&&\sum_{j\in \mathcal{J}_1(x)} |T_rb_j(x)| \\
    \label{eq-b-dec-2}
                &+&&\sum_{j\in \mathcal{J}_2(x)} |T_rb_j(x)| \\
    \label{eq-b-dec-3}
                &+&&\sum_{j\in \mathcal{J}_3(x)} |T_rb_j(x)|.
