n31510.content:
\begin{lemma}[integer ball cover]
    \label{integer-ball-cover}
    \leanok
    \lean{integer_ball_cover}
    For every $x\in {\mathbb{R}}$ and $R>0$ and every
    $n\in \mathbb{Z}$ and $R'>0$,
    there exist $m_1, m_2, m_3\in \mathbb{Z}$
    such that
    \begin{equation}\label{eqcarl5}
        B'\subset B_1\cup B_2\cup B_3\, ,
    \end{equation}
where
\begin{equation}
B'= \{ {\vartheta}\in {\Theta}: d_{B(x,R)}({\vartheta}, {\vartheta}_n)<2R'\}
\end{equation}
and for $j=1,2,3$
\begin{equation}
  B_j=
     \{ {\vartheta}\in {\Theta}: d_{B(x,R)}({\vartheta}, {\vartheta}_{m_j})<R'\}
     \, .
\end{equation}
\end{lemma}

n31511.content:
\begin{proof}
\leanok
Let $m_1$ be the largest integer smaller than
or equal to
$n- \frac {R'}{2R}$.
Let $m_2=n$.
Let $m_3$ be the smallest integer larger than
or equal to $n+ \frac {R'}{2R}$.

Let ${\vartheta}_{n'}\in B'$, then with \eqref{eqcarl4},
we have
\begin{equation}\label{eqcarl6}
    2R|n-n'|< 2R'\, .
\end{equation}

Assume first $n'\le m_1$. With \eqref{eqcarl6}
we have
\begin{equation*}
    R|m_1-n'|=R(m_1-n')=R(m_1-n)+R(n-n')
\end{equation*}
\begin{equation}
    < -\frac{R'}2+R'=-\frac{R'}2\, .
\end{equation}
We conclude ${\vartheta}_{n'}\in B_1$.

Assume next $m_1<n'<m_3$. Then
${\vartheta}_{n'}\in B_2$.

Assume finally that $m_3\le n'$. With \eqref{eqcarl6}
we have
\begin{equation*}
    R|m_3-n'|=R(n'-m_3)=R(n'-n)+R(n-m_3)
\end{equation*}
\begin{equation}
    < R' -\frac{R'}2=-\frac{R'}2\, .
\end{equation}
We conclude ${\vartheta}_{n'}\in B_1$.
This completes the proof of the lemma.
\end{proof}

n31512.content:
\begin{lemma}[real van der Corput]
\label{real-van-der-Corput}
\leanok
\lean{real_van_der_Corput}
\uses{van-der-Corput}
    For any $x\in {\mathbb{R}}$ and $R>0$ and any
    function $\varphi: X\to \C$ supported on $B'=B(x,R)$
    such that
\begin{equation}
    \|\varphi\|_{\Lip(B')} = \sup_{x \in B'} |\varphi(x)| + R \sup_{x,y \in B', x \neq y} \frac{|\varphi(x) - \varphi(y)|}{\rho(x,y)}
\end{equation}
is finite and for any $n,m\in \mathbb{Z}$, we have
\begin{equation}
    \label{eq-vdc-cond1}
    \left|\int_{B'} e({\vartheta}_n(x)-{{\vartheta}_m(x)}) \varphi(x) d\mu(x)\right|\le 2\pi \mu(B')\frac{\|\varphi\|_{\Lip(B')}}{1+d_{B'}({\vartheta}_n,{\vartheta}_m)}
\, .
\end{equation}
\end{lemma}

n31513.content:
\begin{proof}
    \leanok
Set $n'=n-m$. Then we have to prove
\begin{equation}
    \label{eq-vdc-cond2}
    \left|\int_{x-R}^{x+R} e^{in'y}\varphi(y) dy\right|\le 4\pi R\|\varphi\|_{\Lip(B')}
(1+2R|n'|)^{-1}\, .
\end{equation}
This follows from \Cref{van-der-Corput} with $\alpha = x - R$ and $\beta = x + R$.
\end{proof}
